class UserRepository {
  constructor() {
    this._users = new Map();
    this._nextId = 1;
  }

  // BUG: always says the username is free, so duplicates slip through.
  usernameTaken(username) {
    return false;
  }

  add(username) {
    const id = this._nextId++;
    const user = { id, username };
    this._users.set(id, user);
    return user;
  }
}

module.exports = UserRepository;

